-- Historical Zelená liga table (previously an embedded Google Sheet), editable from the editorial section.
create table if not exists public.content_league_history_columns (
  season_label text primary key,
  ordinal text not null default '',
  order_index integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.content_league_history_rows (
  id uuid primary key default gen_random_uuid(),
  troop_number text not null default '',
  name text not null,
  order_index integer not null default 0,
  points jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.set_content_league_history_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists set_content_league_history_columns_updated_at on public.content_league_history_columns;
create trigger set_content_league_history_columns_updated_at before update on public.content_league_history_columns for each row execute function public.set_content_league_history_updated_at();
drop trigger if exists set_content_league_history_rows_updated_at on public.content_league_history_rows;
create trigger set_content_league_history_rows_updated_at before update on public.content_league_history_rows for each row execute function public.set_content_league_history_updated_at();

alter table public.content_league_history_columns enable row level security;
alter table public.content_league_history_rows enable row level security;

